def build_nouns_places_nature_bundle(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    for row in RAW_NATURE_PLACES:
        headword = row[0]
        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        gender = row[1]
        level = row[2]
        msa = row[3]
        eg = row[4]
        domain = row[5]
        ex_es = row[6]
        ex_ar = row[7]

        entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-nouns-places-nature.json",
        bundle_slug="cv-nouns-places-nature",
        title_ar="أسماء الأماكن والمدينة والطبيعة والجغرافيا والكائنات",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_nouns_places_nature_bundle(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-nouns-places-nature.json")
